    49	    // The panel's first line, shown as the agent's. Returns its message id.
    50	    virtual std::string post_opening(const std::string& text) = 0;
    51	    // The model answers next, from the conversation as it stands.
    52	    virtual void start_turn() = 0;
    53	    // The cards in the thread, or what the model is told, have changed.
    54	    virtual void session_changed() = 0;
    55	    // The page sent new instructions for the model.
    56	    virtual void profile_changed() = 0;
    57	    // The panel is done: back to Home.
