                                        return printer.id == "BBL/Bambu Lab A1 mini";
                                    });
                                    if (entry == catalog.end())
                                        return;
                                    PrinterSetup::AddPrinterRequest request{entry->vendor_id, entry->model_id, "0.4",
                                                                            entry->filament_for(0.4), entry->display_name(), {}};
                                    PrinterSetup::SavedPrinter added;
