                                    live_backend().prepare_connection(m_live_added.empty() ? std::string() : m_live_added.front());
                                },
                                [this] {
                                    return !m_live_added.empty() &&
                                           !live_backend().connection(m_live_added.front()).candidates.empty();
                                },
                                [this] {
                                    for (const auto& candidate : live_backend().connection(m_live_added.front()).candidates)
                                        std::cerr << "HARNESS LIVE   found " << candidate.id << ' ' << candidate.name
                                                  << (candidate.lan_mode ? " (LAN)" : " (account)") << '\\n';
                                }});

        for (int trial = 1; trial <= trials; ++trial) {
            const std::string name = "trial " + std::to_string(trial) + "/" + std::to_string(trials);
            m_live_steps.push_back({name + " open: connect",
                                    [this] {
                                        for (const Agent::ToolActivity* call : live_calls("printer_connect"))
                                            m_trial_seen.insert(call->action_id);
                                        m_trials.emplace_back();
                                        live_show(Mode::Connect, m_live_added.empty() ? std::string() : m_live_added.front());
                                        m_live_printed = 0;
                                    },
                                    [this] { return live_panel()->host() != nullptr && live_panel()->host()->handshake_complete() && live_panel()->instructions_ready(); },
                                    {}});
            // The script of --printer-live's connect step: confirm the
            // printer, then ask again only if the card is not up yet.
            m_live_steps.push_back({name + " say: Yes, it is", [this] { trial_say("Yes, it is"); }, {}, {}});
            m_live_steps.push_back({name + " say, if still asked: Yes, connect it",
                                    [this] {
                                        const auto calls = trial_calls();
                                        if (calls.empty() || calls.back()->state != Agent::ToolState::Pending)
                                            trial_say("Yes, connect it");
                                    },
                                    {},
                                    [this, name] {
                                        live_print_calls();
                                        ConnectTrial& result = m_trials.back();
                                        for (const Agent::ToolActivity* call : trial_calls()) {
                                            if (call->state == Agent::ToolState::Pending)
                                                result.card = true;
                                            else if (call->error)
                                                result.refused.push_back(call->arguments_json + " -> " + call->error->code);
                                        }
                                        std::cerr << "HARNESS TRIAL " << name << ": " << (result.card ? "card" : "NO CARD");
                                        for (const std::string& refused : result.refused)
                                            std::cerr << "; refused " << refused;
                                        std::cerr << '\\n';
                                    }});
            // Put the card down, as Cancel would, so nothing waits into the
            // next trial.
            m_live_steps.push_back({name + " cancel the card",
                                    [this] {
                                        const auto calls = trial_calls();
                                        if (!calls.empty() && calls.back()->state == Agent::ToolState::Pending)
                                            live_send("tool_decision", {{"actionId", calls.back()->action_id}, {"decision", "reject"}});
                                    },
                                    {},
                                    {}});
        }

        m_live_steps.push_back({"trials: summary", [] {}, [] { return true; }, [this, trials, must_reach] {
                                    int cards = 0, refused = 0;
                                    for (const ConnectTrial& trial : m_trials) {
                                        cards += trial.card ? 1 : 0;
                                        refused += trial.refused.empty() ? 0 : 1;
                                    }
