+    // --- Connecting, repeated (--printer-connect-trials N) -----------------
+    //
+    // One step of the live model's work, measured rather than assumed: the
+    // same "connect this printer" conversation, each time in a new session,
+    // against the in-process fake Bambu Lab printer. A trial reaches the card
+    // when the model calls printer_connect with a printer the app accepts;
+    // every call the app refused on the way is reported with its arguments.
+    // One run is one sample of a model that answers differently each time, so
+    // the result is a count, and a change to the printer panel's system
+    // prompt (printerInstructions.ts) is judged by comparing counts.
+
+    struct ConnectTrial
+    {
+        bool                     card{false};
+        std::vector<std::string> refused; // "arguments -> error code"
+    };
+    std::vector<ConnectTrial> m_trials;
