+                                                                            entry->filament_for(0.4), entry->display_name(), {}};
+                                    PrinterSetup::SavedPrinter added;
+                                    if (live_backend().add_printer(request, added).empty() && !added.name.empty())
+                                        m_live_added.push_back(added.name);
+                                },
+                                [] { return true; },
+                                [this] { check(m_live_added.size() == 1, "trials_printer_saved"); }});
+        // Found on the network before any conversation, as in --printer-live,
+        // so each trial is about the conversation, not discovery.
